def generate_tile(signal_value):
    if signal_value == 1:
        # 2x2 pattern from demo: row 0 has [1,1], row 1 has [1,0]
        return [[1, 1], [1, 0]]
    elif signal_value == 3:
        # 3x3 pattern from demo: [0,3,0; 3,0,3; 3,3,3]
        return [[0, signal_value, 0], [signal_value, 0, signal_value], 
